package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Runs early in the create-owner pipeline (before {@link RequireOwnerFields}): normalizes the
 * {@code address} to its canonical form (see {@link AddressNormalizer}). The normalized value is
 * written back onto the (shared) {@link OwnerFieldsDto} so {@link RequireOwnerFields} rejects an
 * address that is blank after normalization, {@link RequireUniqueHousehold}/{@link AssignHousehold}
 * compare the normalized form, {@link BuildOwner} stores it and {@code GET /owners/{id}} later
 * returns it.
 */
public class NormalizeOwnerAddress {

    public void service(@Val OwnerFieldsDto owner) {
        owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * The single definition of the E.164 form of a telephone number. Shared by
 * {@link NormalizeOwnerTelephone} (which stores the E.164 value) and {@link RequireUniqueTelephone}
 * (which compares against it), so both apply the same rule and cannot drift apart.
 *
 * <p>The rule: strip spaces, dashes and brackets. When a leading {@code '+'} is present, keep it and
 * the country code that follows; otherwise assume country code {@code '+61'} and drop a single leading
 * {@code '0'} from the national digits. The result must carry 8 to 15 digits after the {@code '+'};
 * anything else cannot form valid E.164 and yields {@code null}.
 *
 * <p>The national-number length is also checked against the country code: {@code '+61'} (Australia)
 * requires exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10. A number for one of
 * those countries whose national part is the wrong length cannot form valid E.164 and yields
 * {@code null} (rejected with a 400). Other country codes keep only the generic 8-to-15 length rule.
 *
 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
 * expose exactly one public method.
 */
final class TelephoneNormalizer {

    /**
     * Country code (the digits after the {@code '+'}) to its required national-number length. Country
     * codes absent here keep only the generic 8-to-15 rule. Adding a country is a new entry, not a new
     * branch.
     */
    private static final Map<String, Integer> NATIONAL_LENGTH = Map.of("61", 9, "1", 10);

    /**
     * Returns the E.164 form of the given telephone, or {@code null} when it cannot form a valid one.
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        // Strip spaces, dashes and brackets.
        String cleaned = telephone.replaceAll("[\\s()-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            // Explicit country code: keep the digits that follow the '+'.
            digits = cleaned.substring(1);
        }
        else {
            // No country code: assume +61 and drop a single leading '0' from the national digits.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        // Everything after the '+' must be 8 to 15 digits.
        if (!digits.matches("\\d{8,15}")) {
            return null;
        }
        // Per-country national-number length: +61 (Australia) needs 9 national digits, +1 (NANP)
        // needs 10. Country codes not listed keep only the generic 8-to-15 rule above.
        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH.entrySet()) {
            String countryCode = entry.getKey();
            if (digits.startsWith(countryCode)
                    && digits.length() - countryCode.length() != entry.getValue()) {
                return null;
            }
        }
        return "+" + digits;
    }

    private TelephoneNormalizer() {
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.util.UUID;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of what makes owners share a household: the same last name (compared
 * case-insensitively after collapsing runs of whitespace) and the same address in its normalized
 * form (see {@link AddressNormalizer}). Shared by {@link RequireUniqueHousehold} (which rejects an
 * un-flagged duplicate) and {@link AssignHousehold} (which links a {@code sharesHousehold} owner to
 * the existing members), so both apply the same rule and cannot drift apart.
 *
 * <p>Also owns the deterministic {@code householdId} derived from that key: joining the same household
 * always yields the same value and it never changes over time.
 *
 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
 * expose exactly one public method.
 */
final class HouseholdKey {

    private final String lastName;

    private final String address;

    private HouseholdKey(String lastName, String address) {
        this.lastName = lastName;
        this.address = address;
    }

    /** The household key for the given last name and address. */
    static HouseholdKey of(String lastName, String address) {
        return new HouseholdKey(normalize(lastName), AddressNormalizer.normalize(address));
    }

    /** True when the existing owner belongs to this household. */
    boolean matches(Owner owner) {
        return this.lastName.equals(normalize(owner.getLastName()))
                && this.address.equals(AddressNormalizer.normalize(owner.getAddress()));
    }

    /** A stable, shared identifier derived from the normalized last name and address. */
    String householdId() {
        String key = this.lastName + "\u0000" + this.address;
        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
    }

    /** Lower-cases and collapses runs of whitespace to a single space for case- and
     *  whitespace-insensitive comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

